let cached: Buffer | undefined;

/** The font file as a Buffer (decoded once per process). */
export function dmMonoRegular(): Buffer {
  cached ??= Buffer.from(DM_MONO_REGULAR_BASE64, "base64");
  return cached;
}

/** The same bytes as a standalone ArrayBuffer, the shape `ImageResponse` fonts take. */
export function dmMonoRegularArrayBuffer(): ArrayBuffer {
  const buffer = dmMonoRegular();
  const copy = new ArrayBuffer(buffer.byteLength);
  new Uint8Array(copy).set(buffer);
  return copy;
}
